DataBuf_AllocAndLoadFormatted:
	lda xsp, (xsp - 16)
	push xiz
	ld (xsp + 18), a
	pushw 0x800
	call Malloc
	inc 2, xsp
	ld (xsp + 6), xhl
	ld xwa, (xsp + 6)
	or xwa, xwa
	jr nz, DataBuf_AllocAndLoadFormatted_AllocOk
	ldw hl, 0xFF38
	jrl DataBuf_AllocAndLoadFormatted_Return

DataBuf_AllocAndLoadFormatted_AllocOk:
	pushw 0x800
	ld c, (xsp + 20)
	extz bc
	sla bc, 11
	lda_24 xwa, 0x0ab000
	st_dri3b W, 0x07, 0xE0, 0xE4
	push xwa
	ld xwa, (xsp + 12)
	push xwa
	call Mem_Copy
	lda xsp, (xsp + 10)
	ld xwa, (xsp + 6)
	st_dri3b W, 0xE1, 0xE0, 0x02
	ld (xsp + 10), xwa
	ld a, (xsp + 18)
	extz wa
	inc 1, wa
	calr DataBuf_InitSlotFromPreset
	ld c, (xsp + 18)
	extz bc
	sla bc, 11
	lda_24 xwa, 0x0ab000
	st_dri3b W, 0x07, 0xE0, 0xE4
	ld (xsp + 14), xwa
	ld xwa, 0x2E0
	add (xsp + 14), xwa
	ldw (xsp + 4), 0x0

DataBuf_TransferVoiceParams_Loop:
	ld wa, (xsp + 4)
	extz xwa
	ld xbc, xwa
	sll xbc, 5
	add xbc, 0x20
	ld xiz, xbc
	add xiz, (xsp + 10)
	ld xbc, 0x1A
	call Math_MultiplyAccumulate
	add xhl, 0x34
	add xhl, (xsp + 14)
	ld xwa, xiz
	ld xbc, xhl
	calr DataBuf_CopyVoiceBlock24
	incm 1, (xsp + 4)
	cpw (xsp + 4), 0x18
	jr c, DataBuf_TransferVoiceParams_Loop
	ldw (xsp + 4), 0x0

DataBuf_TransferEffectParams_Loop:
	ld wa, (xsp + 4)
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	sll xbc, 2
	ld xwa, xbc
	add xwa, 0x320
	add xwa, (xsp + 10)
	add xbc, 0x2A4
	add xbc, (xsp + 14)
	calr DataBuf_CopyEffectBlock12
	incm 1, (xsp + 4)
	cpw (xsp + 4), 0x3
	jr c, DataBuf_TransferEffectParams_Loop
	ld xwa, (xsp + 10)
	st_dri3b W, 0xE1, 0x44, 0x03
	ld xbc, (xsp + 14)
	st_dri3b A, 0xE5, 0xD8, 0x02
	calr DataBuf_CopyFilterBlock12
	ld xwa, (xsp + 10)
	st_dri3b W, 0xE1, 0x54, 0x03
	ld xbc, (xsp + 14)
	st_dri3b A, 0xE5, 0xE4, 0x02
	calr DataBuf_CopyReverbBlock6
	ld xwa, (xsp + 10)
	st_dri3b W, 0xE1, 0x5C, 0x03
	ld xbc, (xsp + 14)
	st_dri3b A, 0xE5, 0xEC, 0x02
	calr DataBuf_CopySimpleBlock4
	ldw (xsp + 4), 0x0

DataBuf_TransferAuxParams_Loop:
	ld wa, (xsp + 4)
	extz xwa
	ld xbc, xwa
	sll xbc, 5
	add xbc, 0x36A
	ld xiz, xbc
	add xiz, (xsp + 10)
	ld xbc, 0x1A
	call Math_MultiplyAccumulate
	add xhl, 0x2F2
	add xhl, (xsp + 14)
	ld xwa, xiz
	ld xbc, xhl
	calr DataBuf_LoadAndDispatchFormat2
	incm 1, (xsp + 4)
	cpw (xsp + 4), 0x2
	jr c, DataBuf_TransferAuxParams_Loop
	ld xwa, (xsp + 10)
	st_dri3b W, 0xE1, 0xAA, 0x03
	ld xbc, (xsp + 14)
	st_dri3b A, 0xE5, 0x80, 0x03
	calr DataBuf_CopyEQBlock7
	ld xwa, (xsp + 10)
	st_dri3b W, 0xE1, 0xB8, 0x03
	ld xbc, (xsp + 14)
	st_dri3b A, 0xE5, 0x8A, 0x03
	calr DataBuf_CopyChorusBlock16
