	ld xbc, (xsp + 14)
	st_dri3b A, 0xE5, 0xCE, 0x03
	calr DataBuf_CopyMixerBlock12
	ld xwa, (xsp + 10)
	ld xbc, (xsp + 14)
	calr DataBuf_CopyBulkBitfields_Nop
	ld xwa, 0xF980
	ld xbc, (xsp + 14)
	calr DataBuf_CopyBulkBitfields_F980
	ld xwa, (xsp + 6)
	push xwa
	call Free
	inc 4, xsp
	lds hl, 0

DataBuf_AllocAndLoadFormatted_Return:
	pop xiz
	lda xsp, (xsp + 16)
	ret

